fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Pre-allocate enough space for both v1 and v2
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // Copy all elements of v1
    result.extend_from_slice(v1);
    // Copy all elements of v2
    result.extend_from_slice(v2);
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // Assume `first` is non-empty as per the problem statement.
    let prefix_len = first.len() - 1;
    // Pre-allocate enough space for (len(first)-1) + len(second)
    let mut result = Vec::with_capacity(prefix_len + second.len());
    // Copy all but the last element of `first`
    result.extend_from_slice(&first[..prefix_len]);
    // Append all elements of `second`
    result.extend_from_slice(second);
    result
}

